/**
 * Site-wide SEO constants and URL helpers.
 * Shared by the app (client-side head updates) and vite.config.ts (build-time pre-render + sitemap),
 * so keep this file free of browser/DOM APIs.
 */

export type Language = 'es' | 'en'

export const SITE_URL = 'https://ing-soraire.24studio.net'
export const SITE_NAME = 'Sebastián Soraire'
/** Text shown in the browser tab on every page; the per-page SEO titles still feed Open Graph and Twitter. */
export const TAB_TITLE = 'Ing. S.Soraire'
/** 1200×630, generated by `pnpm og-image` (scripts/generate-og-image.mjs). */
export const OG_IMAGE = '/og-image.png'

/** Spanish lives at the root ("/about"), English under "/en" ("/en/about"). */
export const DEFAULT_LANGUAGE: Language = 'es'
export const LANGUAGES: Language[] = ['es', 'en']

export const OG_LOCALE: Record<Language, string> = { es: 'es_AR', en: 'en_US' }

/** "/about" + "en" -> "/en/about". Expects a language-less path. */
export const localizePath = (path: string, lang: Language): string => {
  if (lang === DEFAULT_LANGUAGE) return path
  return path === '/' ? `/${lang}` : `/${lang}${path}`
}

/** "/en/about" -> { lang: 'en', path: '/about' }; "/about" -> { lang: 'es', path: '/about' } */
export const parsePath = (pathname: string): { lang: Language; path: string } => {
  const clean = pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname
  for (const lang of LANGUAGES) {
    if (lang === DEFAULT_LANGUAGE) continue
    if (clean === `/${lang}`) return { lang, path: '/' }
    if (clean.startsWith(`/${lang}/`)) return { lang, path: clean.slice(lang.length + 1) }
  }
  return { lang: DEFAULT_LANGUAGE, path: clean || '/' }
}

export const absoluteUrl = (path: string) => `${SITE_URL}${path}`
